  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "Ketoprofen absolute oral bioavailability was calculated as ≥92% versus IV at a 100 mg oral dose in humans, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Terodiline absolute oral bioavailability in healthy volunteers ranged from 64% to 105% with a mean of 92% after oral tablets versus IV, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Diphenhydramine absolute oral bioavailability at a 50-mg pharmacological dose was reported as 72% in humans, above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved evidence molecules show quantitative oral bioavailability values at or above 20%, with most well above the threshold; the only variable molecule still has a strongest absolute measurement of 28%, supporting a high bioavailability prediction.",
  "evidence_gaps": [
    "Labetalol has heterogeneous literature values, including some below 20%, but its strongest absolute measurement (28%, range 19–49%) is above threshold, introducing minor uncertainty.",
    "Some records are qualitative or from special populations/conditions, but quantitative absolute measurements dominate the decision."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

